import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        // Leitura robusta de toda a entrada (tokens separados por whitespace)
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sbIn = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sbIn.append(line).append(' ');
        }
        StringTokenizer tok = new StringTokenizer(sbIn.toString());
        int n = Integer.parseInt(tok.nextToken());
        int f = Integer.parseInt(tok.nextToken());

        char[][] grid = new char[n][];
        for (int i = 0; i < n; i++) {
            grid[i] = tok.nextToken().toCharArray();
        }

        // BFS (flood fill) a partir do canto superior esquerdo,
        // somente se a própria posição inicial puder ser invadida.
        if (grid[0][0] - '0' <= f) {
            int[] queue = new int[n * n];
            int head = 0, tail = 0;
            grid[0][0] = '*';
            queue[tail++] = 0;

            while (head < tail) {
                int cur = queue[head++];
                int r = cur / n, c = cur % n;

                if (r > 0 && grid[r - 1][c] != '*' && grid[r - 1][c] - '0' <= f) {
                    grid[r - 1][c] = '*';
                    queue[tail++] = cur - n;
                }
                if (r < n - 1 && grid[r + 1][c] != '*' && grid[r + 1][c] - '0' <= f) {
                    grid[r + 1][c] = '*';
                    queue[tail++] = cur + n;
                }
                if (c > 0 && grid[r][c - 1] != '*' && grid[r][c - 1] - '0' <= f) {
                    grid[r][c - 1] = '*';
                    queue[tail++] = cur - 1;
                }
                if (c < n - 1 && grid[r][c + 1] != '*' && grid[r][c + 1] - '0' <= f) {
                    grid[r][c + 1] = '*';
                    queue[tail++] = cur + 1;
                }
            }
        }

        StringBuilder sb = new StringBuilder(n * (n + 1));
        for (int i = 0; i < n; i++) {
            sb.append(grid[i]).append('\n');
        }
        System.out.print(sb);
    }
}
